    'UI_STRATEGY_FULL_TOOLTIPS' => "完全備份將會對備份源的全部資料進行備份,備份完成後備份資料成為一個完全備份時間點,備份的是所有資料",
    'UI_STRATEGY_INCR_TOOLTIPS' => "增量備份是在上一次備份的基礎上對來源資料進行備份,依賴上一個增量時間點或者完備時間點,只備份上一次備份完成到當前時間的變化資料",
    'UI_STRATEGY_DIFF_TOOLTIPS' => "差異備份是在上一次完全備份的基礎上對來源資料進行備份,依賴上一個完全備份點,只備份上一次完全備份完成到當前時間的變化資料",
    'UI_STRATEGY_PINCR_TOOLTIPS' => "永久增量为，在做备份任务时，只需做一次完全备份，以后只做增量备份。永久增量只做一次完全备份，减少完全备份次数，节省备份存储空间及带宽资源",
    'UI_STRATEGY_THREE_TOOLTIPS' => "一般情況下,建議每週/每月做一次完全備份,每天做一次增量備份,增量備份和差異備份不能同時設置,如果只設置了增量備份或差異備份,任務首次會自動降級為完全備份",
    'UI_STRATEGY_LOG_TOOLTIPS_MYSQL' => "日誌備份是在上一次日誌備份或完全備份的基礎上,對比變化的日誌資料",
    'UI_STRATEGY_LOG_TOOLTIPS_SQLSERVER' => "日誌備份是在上一次備份的基礎上,對變化的日誌資料進行備份,依賴于上一個日誌時間點或增加時間點或差異時間點或完備時間點",
