    'UI_BACKUP_TRANSPORT_HOT_VMWARE' => "熱添加傳輸",
    'UI_BACKUP_TRANSPORT_SELECT_TIPS' => "網路傳輸:備份資料將通過LAN網路傳輸到備份存儲<br><br>SAN傳輸(LAN-Free):備份資料通過SAN傳輸到備份存儲,需要先配置LAN-Free存儲<br><br>網路加密傳輸 : 備份資料通過SSL加密傳輸<br><br>熱添加傳輸(LAN-Free) : 備份資料通過SAN網路把磁片附加到備份伺服器上,需要先配置LAN-Free存儲<br><br>如果SAN傳輸未生效,會自動使用網路傳輸",
    'UI_BACKUP_TRANSPORT_VMWARE_SELECT_TIPS' => "網路傳輸:備份資料將通過LAN網路傳輸到備份存儲<br><br>SAN傳輸(LAN-Free):備份資料通過SAN傳輸到備份存儲,需要先配置LAN-Free存儲<br><br>網路加密傳輸 : 備份資料通過SSL加密傳輸<br><br>熱添加傳輸 : 通過ESXI的SCSI HotAdd特性將目標磁片掛載到備份服務器/代理上，實現數據的直接訪問<br><br>如果SAN傳輸未生效,會自動使用網路傳輸",
    'UI_BACKUP_TRANSPORT_ICS_VVDK_SELECT_TIPS' => "網路傳輸:備份資料將通過LAN網路傳輸到備份存儲",
    'UI_BACKUP_TRANSPORT_SELECT_NBD_TIPS' => '【網絡會自動切換，若有專用備份網絡則優先使用專用網絡傳輸，否則才會切換至管理網絡進行傳輸】',
    'UI_BACKUP_TRANSPORT_HUAWEI_KVM_SELECT_TIPS' => "NBD傳輸:通過虛擬化平臺提供的介面將備份資料傳輸到備份存儲介質",
    'UI_BACKUP_TRANSPORT_RHV_SELECT_TIPS' => "網路傳輸:備份資料將通過LAN網路傳輸到備份存儲<br><br>SAN傳輸(LAN-Free):備份資料通過SAN傳輸到備份存儲,需要先配置LAN-Free存儲<br><br>ImageIO傳輸:通過虛擬化平臺提供的介面將備份資料傳輸到備份存儲介質",
    'UI_BACKUP_TRANSPORT_HUAWEI_SELECT_TIPS' => "網路傳輸:備份資料將通過LAN網路傳輸到備份存儲<br><br>SAN傳輸(LAN-Free):備份資料通過SAN傳輸到備份存儲,需要先配置LAN-Free存儲<br><br>網路加密傳輸 : 備份資料通過SSL加密傳輸<br><br>如果SAN傳輸未生效,會自動使用網路傳輸",
