    'UI_BACKUP_TRANSPORT_XENSERVER_SELECT_TIPS' => "網路傳輸:備份資料將通過LAN網路傳輸到備份存儲<br><br>SAN傳輸(LAN-Free):備份資料通過SAN傳輸到備份存儲,需要先配置LAN-Free存儲<br><br>NBD傳輸:通過虛擬化平臺提供的介面將備份資料傳輸到備份存儲介質,XenServer7.3及以上支援<br><br>SAN+NBD傳輸:備份資料通過NBD方式SAN傳輸到備份存儲<br><br>如果SAN傳輸未生效,會自動使用網路傳輸",
