    'UI_DB_SOME_CONFIG_BEFORE_ORACLE_BACKUP' => "進行Oracle資料庫恢復之前，要對恢復的目標伺服器做一些配置，這些配置請由資料庫管理員來完成",
    'UI_DB_SOME_CONFIG_BEFORE_ORACLE_BACKUP_TIPSONE' => "1.恢復前請關閉資料庫",
    'UI_DB_SOME_CONFIG_BEFORE_ORACLE_BACKUP_TIPSTWO' => "2.目標資料庫伺服器的資料庫配置要與備份的來源資料庫伺服器基本一致，包括作業系統版本、資料庫版本、安裝資料庫的路徑、用戶名、密碼、實例名等",
    'UI_DB_SOME_CONFIG_BEFORE_ORACLE_BACKUP_TIPSTHREE' => "3.目標資料庫伺服器要配置靜態監聽，以確保恢復程式在該資料庫處於關閉狀態時仍能登錄到資料庫中",
    'UI_DB_SOME_CONFIG_BEFORE_ORACLE_BACKUP_TIPSFOUR' => "4.目標伺服器的資料庫實例需要開啟歸檔模式",
    'UI_DB_SOME_CONFIG_BEFORE_ORACLE_BACKUP_TIPSFIVE' => "5.如果恢復的目標資料庫伺服器不是原機的話，還需要刪除目標伺服器中的歸檔日誌檔和REDO檔",
    'UI_DB_CONFIG_BEFORE_MYSQL_BACKUP_TIPS' => "恢復SQL Server資料庫前不需要配置目標資料庫伺服器，但是要求目標資料庫伺服器的配置要與備份的來源資料庫配置基本一致，包括安裝資料庫的路徑、用戶名、密碼、實例名等",
    'UI_DB_OPERATION_BEFORE_MYSQL_BACKUP' => "因為涉及到停止資料庫服務和修改資料庫目錄，進行MySQL資料庫恢復之前的準備請由資料庫管理員來進行操作",
    'UI_DB_OPERATION_BEFORE_MYSQL_BACKUP_TIPSONE' => "1.恢復資料庫前需要停止MySQL資料庫服務",
    'UI_DB_OPERATION_BEFORE_MYSQL_BACKUP_TIPSTWO' => "2.如果選擇原資料庫覆蓋恢復，目標資料庫伺服器的資料庫配置要與備份的來源資料庫伺服器基本一致，包括作業系統版本、資料庫版本、資料庫的用戶名、密碼等",
    'UI_DB_OPERATION_BEFORE_MYSQL_BACKUP_TIPSTHREE' => "3.清空恢復目標伺服器的資料庫資料目錄datadir，清空前可以先複製一份原來的datadir目錄下的資料",
    'UI_DB_OPERATION_BEFORE_MYSQL_BACKUP_TIPSFOUR' => "4.新建一個空目錄作為臨時目錄存放恢復中產生的緩存資料，臨時目錄最好與資料目錄在同一個分區",
    'UI_DB_OPERATION_BEFORE_MYSQL_BACKUP_TIPSFIVE' => "5.如果要恢復日誌備份點則目標資料庫伺服器需要開啟binlog模式",
    'UI_DB_CONFIG_BEFORE_DM_RECOVER' => "進行DM資料庫恢復之前，要對恢復的目標伺服器做一些配置，這些配置請由資料庫管理員來完成",
    'UI_DB_CONFIG_BEFORE_DM_RECOVER_TIPSONE' => "1.原資料庫覆蓋恢復前請關閉資料庫",
    'UI_DB_CONFIG_BEFORE_DM_RECOVER_TIPSTWO' => "2.如果選擇原資料庫覆蓋恢復，目標資料庫伺服器的資料庫配置要與備份的來源資料庫伺服器基本一致，包括作業系統版本、資料庫版本、安裝資料庫的路徑、用戶名、密碼、實例名等",
    'UI_DB_CONFIG_BEFORE_DM_RECOVER_TIPSTHREE' => "3.目標伺服器的資料庫實例需要開啟歸檔模式",
    'UI_DB_CONFIG_BEFORE_DM_RECOVER_TIPSFOUR' => "4.如果選擇指定資料夾恢復，則該資料夾要設置為與原資料目錄相同的許可權，恢復完成後啟動資料庫時需要關閉原資料庫並且重新註冊實例的系統服務",
    'UI_DB_SAMETIME_POINT_ROLLBACK_TIPS' => "恢復過程中將資料回滾到一致性時間點時，需要使用的臨時目錄，建議與data目錄放在同一分區。(因為準備完成會將臨時目錄的資料移動到data目錄)",
